// ===========================================================================
//  BỘ NÃO BOT - /size /check (tính nhanh) + /sâu (AI viết nháp ①③⑤).
//  Trả về { route:'direct', chatId, message }  -> gửi thẳng Telegram
//         { route:'ai', chatId, requestBody, prelude } -> qua node Claude
// ===========================================================================
const OWNER = 5239928968;
const NAV   = 5000000;
const MAX_POS_PCT = 100;
const RISK_PCT_DEF = 1.5;
const MAX_ARTICLES = 2;   // số bài thị trường đọc full cho /sâu (mỗi bài ~10s)
// ===========================================================================

const upd = $input.first().json;
const msg = upd.message || upd.channel_post || {};
const text = (msg.text || '').trim();
const chatId = msg.chat && msg.chat.id;
const direct = (m) => [{ json: { route: 'direct', chatId, message: m } }];

if (String(chatId) !== String(OWNER)) return direct('⛔ Bot riêng tư.');

const help = '🤖 *Bot CK — chỉ cần gõ MÃ*\n\n'
  + '🧮 `/size MÃ` — tự tính vùng giá + khối lượng & R:R\n'
  + '🧭 `/check MÃ` — vùng giá + bảng 7 câu (định lượng)\n'
  + '🔬 `/sâu MÃ` — AI đọc tin + dữ liệu, viết NHÁP ①③⑤ _(chậm ~30-60s)_\n\n'
  + '✍️ Tự nhập: `/size MÃ vào cắtlỗ mụctiêu` _(nghìn đồng)_\n'
  + '_Mức & nháp đều là gợi ý để anh phản biện, không phải lệnh mua._';
if (!text || /^\/(start|help)\b/i.test(text)) return direct(help);

const parts = text.split(/\s+/);
const cmd = parts[0].toLowerCase().replace(/@.*$/, '');
const isDeep = /^\/(s[aâ]u|research|deep)$/i.test(cmd);
if (cmd !== '/size' && cmd !== '/check' && !isDeep) return direct('❓ Lệnh không hiểu.\n\n' + help);
const TICKER = (parts[1] || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
if (!TICKER) return direct('⚠️ Thiếu mã. Gõ: `/size BID`, `/check FPT` hoặc `/sâu FPT`');

const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36';
const hBar = { 'User-Agent': UA, 'Accept': '*/*' };
const hFin = { 'User-Agent': UA, 'Accept': 'application/json', 'Referer': 'https://dstock.vndirect.com.vn/' };
const hTxt = { 'User-Agent': UA, 'Accept': 'text/plain, */*' };

// ====================== /sâu — gom dữ liệu + dựng prompt AI ================
if (isDeep) {
  // 1) định giá đầy đủ
  let valuation = '(không lấy được)';
  try {
    const codes = '51006,51012,51011,51033,51007,1000041,1000043,1000050,1000068';
    const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://api-finfo.vndirect.com.vn/v4/ratios?q=code:' + TICKER + '~itemCode:' + codes + '&sort=reportDate:desc&size=60', headers: hFin, json: false, timeout: 15000 });
    let p; try { p = typeof r === 'string' ? JSON.parse(r) : r; } catch (e) { p = null; }
    const m = {}; for (const d of ((p && p.data) || [])) if (!(d.ratioCode in m)) m[d.ratioCode] = d.value;
    const n2 = (v) => v == null ? 'n/a' : Number(v).toFixed(1);
    const pcv = (v) => v == null ? 'n/a' : (Number(v) * 100).toFixed(1) + '%';
    valuation = 'P/E ' + n2(m.PRICE_TO_EARNINGS) + ' (TB 1N/5N: ' + n2(m.PRICE_TO_EARNINGS_AVG_CR_1Y) + '/' + n2(m.PRICE_TO_EARNINGS_AVG_CR_5Y) + ') | P/B ' + n2(m.PRICE_TO_BOOK) + ' (TB5N ' + n2(m.PRICE_TO_BOOK_AVG_CR_5Y) + ') | Cổ tức ' + pcv(m.DIVIDEND_YIELD) + ' | Beta ' + n2(m.BETA) + ' | cách đỉnh 52T ' + pcv(m.PRICE_CHG_PCT_CR_HH52W);
  } catch (e) {}
  // 2) dòng tiền ngoại 10 phiên
  let flow = '(không lấy được)';
  try {
    const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://api-finfo.vndirect.com.vn/v4/foreigns?q=code:' + TICKER + '&size=10&sort=tradingDate:desc', headers: hFin, json: true, timeout: 15000 });
    const nets = ((r && r.data) || []).map(x => (x.netVal || 0) / 1e9);
    if (nets.length) flow = '10 phiên (tỷ, mới→cũ): [' + nets.map(v => v.toFixed(1)).join(', ') + '] · tổng ' + nets.reduce((a, b) => a + b, 0).toFixed(1) + ' tỷ';
  } catch (e) {}
  // 3) tiêu đề tin về mã
  let headlines = '(không lấy được)';
  try {
    const url = 'https://news.google.com/rss/search?q=' + encodeURIComponent('"' + TICKER + '" cổ phiếu when:7d') + '&hl=vi&gl=VN&ceid=VN:vi';
    const body = await this.helpers.httpRequest({ method: 'GET', url, headers: { 'User-Agent': UA, 'Accept': '*/*' }, json: false, timeout: 15000 });
    const xml = String(body);
    const titles = (xml.match(/<item[\s\S]*?<\/item>/gi) || []).slice(0, 8).map(it => { const m = it.match(/<title>([\s\S]*?)<\/title>/i); return m ? m[1].replace(/<!\[CDATA\[/g, '').replace(/\]\]>/g, '').replace(/&amp;/g, '&').trim() : ''; }).filter(Boolean);
    if (titles.length) headlines = titles.map((t, i) => (i + 1) + '. ' + t).join('\n');
  } catch (e) {}
  // 4) bối cảnh thị trường full-text (Jina + Vietstock)
  let context = '(không lấy được)';
  try {
    const jina = async (u) => String(await this.helpers.httpRequest({ method: 'GET', url: 'https://r.jina.ai/' + u, headers: hTxt, json: false, timeout: 40000 }));
    const rss = await jina('https://vietstock.vn/145/chung-khoan/thi-truong.rss');
    const urls = [...new Set((rss.match(/https?:\/\/(?:[a-z]+\.)?vietstock\.vn\/[^\s)\]"'>]+\.htm/gi) || []))].slice(0, MAX_ARTICLES);
    const arts = [];
    for (const u of urls) { try { const a = await jina(u); const title = (a.match(/Title:\s*([^\n]+)/) || [])[1] || ''; const bd = (a.split('Markdown Content:')[1] || a).replace(/!\[[^\]]*\]\([^)]*\)/g, '').replace(/\[[^\]]*\]\([^)]*\)/g, '').replace(/\s+/g, ' ').trim().slice(0, 1800); if (bd.length > 200) arts.push('• ' + title.trim() + '\n' + bd); } catch (e) {} }
    if (arts.length) context = arts.join('\n\n');
  } catch (e) {}

  const today = new Date().toLocaleDateString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh', day: 'numeric', month: 'numeric', year: 'numeric' });
  const system = 'Bạn là chuyên viên phân tích cổ phiếu cấp cao, viết NHÁP trả lời 3 câu hỏi ĐỊNH TÍNH (①③⑤) cho nhà đầu tư cá nhân về mã ' + TICKER + ', bằng tiếng Việt. Tỉnh táo, hoài nghi, dựa bằng chứng. Đây là NHÁP để nhà đầu tư PHẢN BIỆN, KHÔNG phải khuyến nghị mua/bán.\n\n'
    + 'Độ tin cậy nguồn: DỮ LIỆU CỨNG (định giá, dòng tiền khối ngoại) = đáng tin nhất. TIÊU ĐỀ tin = chưa kiểm chứng, dễ giật tít. BỐI CẢNH (toàn văn) = hiểu môi trường chung.\n\n'
    + 'Trả lời ĐÚNG 3 mục + 1 mục kiểm chứng, mỗi mục 2-5 câu:\n'
    + '*① HIỂU DOANH NGHIỆP:* ' + TICKER + ' kiếm tiền bằng cách nào? Mô hình cốt lõi, vị thế ngành — nói dễ hiểu như giải thích cho người mới.\n'
    + '*③ LUẬN ĐIỂM & PHẢN BIỆN:* nêu 1 luận điểm tăng giá HỢP LÝ dựa trên dữ liệu/tin; rồi BẮT BUỘC nêu "NẾU… THÌ luận điểm SAI" (dấu hiệu/ngưỡng cụ thể) và rủi ro lớn nhất.\n'
    + '*⑤ THỜI ĐIỂM:* có xúc tác ngắn hạn (KQKD, cổ tức, sự kiện) không, hay đang "bắt dao rơi"? Dựa trên tin + dòng tiền ngoại + định giá.\n'
    + '*🔎 CẦN TỰ KIỂM CHỨNG:* nêu rõ những gì dữ liệu này CHƯA có (ROE/nợ/chất lượng tài sản/BCTC gốc) mà nhà đầu tư phải tự tra.\n\n'
    + 'TUYỆT ĐỐI không bịa số. Nguồn nào trống thì nói rõ. Tối đa ~550 từ.';
  const userContent = 'Mã ' + TICKER + ', ngày ' + today + '.\n\n=== ĐỊNH GIÁ (cứng) ===\n' + valuation + '\n\n=== DÒNG TIỀN NGOẠI (cứng) ===\n' + flow + '\n\n=== TIÊU ĐỀ TIN (chưa kiểm chứng) ===\n' + headlines + '\n\n=== BỐI CẢNH TT (toàn văn) ===\n' + context + '\n\nTrả lời ①③⑤ + kiểm chứng.';
  const requestBody = { model: 'claude-opus-4-8', max_tokens: 6000, thinking: { type: 'adaptive' }, system, messages: [{ role: 'user', content: userContent }] };
  const prelude = '🔬 *SOI SÂU — ' + TICKER + '*  _(nháp ①③⑤ để anh phản biện)_';
  return [{ json: { route: 'ai', chatId, requestBody, prelude } }];
}

// ====================== /size /check (tính nhanh) =========================
const aEntry = parts[2] != null ? parseFloat(parts[2]) : NaN;
const aStop = parts[3] != null ? parseFloat(parts[3]) : NaN;
const aTarget = parts[4] != null ? parseFloat(parts[4]) : NaN;
const RISK_PCT = (parts[5] != null && parseFloat(parts[5]) > 0) ? parseFloat(parts[5]) : RISK_PCT_DEF;

const fmtM = (d) => (d / 1e6).toFixed(d < 1e7 ? 2 : 1) + ' triệu';
const fmtP = (k) => Math.round(k * 1000).toLocaleString('vi-VN') + 'đ';
const to = Math.floor(Date.now() / 1000), from = to - 60 * 60 * 24 * 200;
const normBars = (r) => { if (!r || !Array.isArray(r.c) || !r.c.length) return r; const last = r.c[r.c.length - 1]; if (last > 0 && last < 1000) for (const k of ['c', 'o', 'h', 'l']) if (Array.isArray(r[k])) r[k] = r[k].map(x => x * 1000); return r; };
const fetchBars = async (t) => {
  try { const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://services.entrade.com.vn/chart-api/v2/ohlcs/stock', qs: { symbol: t, from, to, resolution: '1D' }, headers: hBar, json: true, timeout: 15000 }); if (r && Array.isArray(r.c) && r.c.length) return normBars(r); } catch (e) {}
  try { const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://dchart-api.vndirect.com.vn/dchart/history', qs: { symbol: t, resolution: 'D', from, to }, headers: { ...hBar, Referer: 'https://dchart.vndirect.com.vn/' }, json: true, timeout: 15000 }); if (r && Array.isArray(r.c) && r.c.length) return normBars(r); } catch (e) {}
  return null;
};
const fetchPE = async (t) => { try { const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://api-finfo.vndirect.com.vn/v4/ratios?q=code:' + t + '~itemCode:51006,1000043&sort=reportDate:desc&size=10', headers: hFin, json: false, timeout: 12000 }); let p; try { p = typeof r === 'string' ? JSON.parse(r) : r; } catch (e) { p = null; } const m = {}; for (const d of ((p && p.data) || [])) if (!(d.ratioCode in m)) m[d.ratioCode] = d.value; return { pe: m['PRICE_TO_EARNINGS'], pe5: m['PRICE_TO_EARNINGS_AVG_CR_5Y'] }; } catch (e) { return {}; } };
const fetchFlow = async (t) => { try { const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://api-finfo.vndirect.com.vn/v4/foreigns?q=code:' + t + '&size=5&sort=tradingDate:desc', headers: hFin, json: true, timeout: 12000 }); return ((r && r.data) || []).map(x => (x.netVal || 0) / 1e9); } catch (e) { return []; } };
const tickOf = (p) => p < 10000 ? 10 : p < 50000 ? 50 : 100;
const roundT = (p) => { const t = tickOf(p); return Math.round(p / t) * t; };
const pivots = (arr, w, kind) => { const r = []; for (let i = w; i < arr.length - w; i++) { let ok = true; for (let k = i - w; k <= i + w; k++) { if (k === i) continue; if (kind === 'low' ? arr[k] < arr[i] : arr[k] > arr[i]) { ok = false; break; } } if (ok) r.push({ i, v: arr[i] }); } return r; };
const dstr = (sec) => new Date(sec * 1000).toLocaleDateString('en-CA', { timeZone: 'Asia/Ho_Chi_Minh' });
const deriveLevels = (bars, entryOverrideK) => {
  const n = bars.c.length, lows = bars.l, highs = bars.h, times = bars.t;
  const closeD = bars.c[n - 1]; const entryD = entryOverrideK > 0 ? entryOverrideK * 1000 : closeD;
  const lookI = Math.max(0, n - 130);
  const pl = pivots(lows, 3, 'low').filter(p => p.i >= lookI && p.v < entryD * 0.997);
  const ph = pivots(highs, 3, 'high').filter(p => p.i >= lookI && p.v > entryD * 1.003);
  const note = [];
  let sup, supDate = null;
  if (pl.length) { const b = pl.reduce((a, x) => x.v > a.v ? x : a); sup = b.v; supDate = dstr(times[b.i]); } else { sup = Math.min(...lows.slice(Math.max(0, n - 20))); note.push('hỗ trợ tạm tính = đáy 20 phiên'); }
  let res, resDate = null;
  if (ph.length) { const b = ph.reduce((a, x) => x.v < a.v ? x : a); res = b.v; resDate = dstr(times[b.i]); } else { const hi = Math.max(...highs.slice(lookI)); if (hi > entryD * 1.01) { res = hi; note.push('kháng cự tạm tính = đỉnh 6 tháng'); } else { res = entryD * 1.08; note.push('⚠️ giá ở vùng đỉnh, mục tiêu tạm +8%'); } }
  let stopD = roundT(sup * 0.985); if (stopD >= entryD) stopD = roundT(entryD * 0.92);
  let targetD = roundT(res); const eD = roundT(entryD);
  if (targetD <= eD) { targetD = roundT(eD * 1.08); note.push('mục tiêu điều chỉnh +8%'); }
  return { eD, stopD, targetD, supD: roundT(sup), resD: roundT(res), supDate, resDate, closeD: roundT(closeD), note };
};

const manual = aEntry > 0 && aStop > 0;
let ENTRY, STOP, TARGET, prov;
if (manual) {
  if (!(aStop < aEntry)) return direct('⚠️ Cắt lỗ phải THẤP HƠN giá vào.');
  ENTRY = aEntry; STOP = aStop; TARGET = aTarget > aEntry ? aTarget : 0; prov = '✍️ _Mức anh tự nhập_';
} else {
  const bars = await fetchBars(TICKER);
  if (!bars || !Array.isArray(bars.c) || bars.c.length < 12) return direct('🔴 Không lấy được dữ liệu giá *' + TICKER + '* (API lỗi hoặc mã sai).\nThử lại sau, hoặc nhập tay: `/' + cmd.slice(1) + ' ' + TICKER + ' vào cắtlỗ mụctiêu`');
  const d = deriveLevels(bars, aEntry);
  ENTRY = d.eD / 1000; STOP = d.stopD / 1000; TARGET = d.targetD / 1000;
  prov = '📐 *Mức bot tự tính:*\n· Vào ≈ giá hiện tại ' + fmtP(d.closeD / 1000) + '\n· Cắt lỗ ' + fmtP(STOP) + ' _(dưới hỗ trợ ' + fmtP(d.supD / 1000) + (d.supDate ? ' lập ' + d.supDate : '') + ')_\n· Mục tiêu ' + fmtP(TARGET) + ' _(kháng cự ' + fmtP(d.resD / 1000) + (d.resDate ? ' lập ' + d.resDate : '') + ')_' + (d.note.length ? '\n· ' + d.note.join('; ') : '');
}

const entryD = ENTRY * 1000, riskPerShare = (ENTRY - STOP) * 1000;
const byRisk = Math.floor((NAV * RISK_PCT / 100) / riskPerShare / 100) * 100;
const byCap = Math.floor((NAV * MAX_POS_PCT / 100) / entryD / 100) * 100;
const shares = Math.max(0, Math.min(byRisk, byCap));
const lotCost = entryD * 100;
const rr = TARGET > ENTRY ? (TARGET - ENTRY) / (ENTRY - STOP) : null;

if (cmd === '/size') {
  const L = ['🧮 *SIZING — ' + TICKER + '*', prov, '_NAV ' + fmtM(NAV) + ' · rủi ro ' + RISK_PCT + '%_', ''];
  if (shares <= 0) { L.push('→ Theo quy tắc rủi ro: chưa nên mua (chưa đủ 1 lô).'); L.push(lotCost <= NAV ? '⚠️ Tối thiểu 1 lô = ' + fmtM(lotCost) + ' (' + (lotCost / NAV * 100).toFixed(0) + '% NAV → tập trung rất cao).' : '🔴 NAV không đủ 1 lô (' + fmtM(lotCost) + ').'); }
  else { L.push('→ *MUA ' + shares.toLocaleString('vi-VN') + ' cp* (' + (shares / 100) + ' lô) = ' + fmtM(shares * entryD) + ' (' + (shares * entryD / NAV * 100).toFixed(0) + '% NAV)'); L.push('→ Rủi ro thực nếu cắt lỗ: *' + fmtM(shares * riskPerShare) + '* (' + (shares * riskPerShare / NAV * 100).toFixed(2) + '% NAV)'); }
  if (rr != null) L.push('→ *R:R ' + rr.toFixed(2) + '*' + (rr < 2 ? ' ⚠️ mỏng (<2)' : ' ✓ ổn'));
  L.push(''); L.push('💡 Muốn hiểu vì sao nên/không mua → gõ `/sâu ' + TICKER + '`');
  return direct(L.join('\n'));
}

const pe = await fetchPE(TICKER);
let q2 = '_thiếu P/E_';
if (pe.pe > 0 && pe.pe5 > 0) { const k = pe.pe / pe.pe5; q2 = 'P/E ' + pe.pe.toFixed(1) + ' vs TB5N ' + pe.pe5.toFixed(1) + ' → ' + (k <= 0.85 ? '🟢 RẺ so lịch sử' : k >= 1.15 ? '🔴 ĐẮT so lịch sử' : '🟡 quanh TB'); }
else if (pe.pe > 0) q2 = 'P/E ' + pe.pe.toFixed(1) + ' _(thiếu TB lịch sử)_';
const nets = await fetchFlow(TICKER);
let q4 = '_không lấy được_';
if (nets.length) { const dir = nets[0] > 1 ? 1 : nets[0] < -1 ? -1 : 0; let st = 0; for (const v of nets) { const s = v > 1 ? 1 : v < -1 ? -1 : 0; if (s === dir && dir) st++; else break; } q4 = 'phiên gần nhất ' + nets[0].toFixed(1) + ' tỷ' + (st >= 2 ? ' · ' + (dir > 0 ? 'GOM' : 'XẢ') + ' ' + st + ' phiên' : '') + ' · tổng 5p ' + nets.reduce((a, b) => a + b, 0).toFixed(1) + ' tỷ'; }
const q6 = (shares >= 100 ? 'mua ' + shares.toLocaleString('vi-VN') + ' cp (' + (shares * entryD / NAV * 100).toFixed(0) + '% NAV)' : (lotCost <= NAV ? '⚠️ chỉ đủ ~1 lô (' + (lotCost / NAV * 100).toFixed(0) + '% NAV)' : '🔴 NAV không đủ 1 lô')) + ' · R:R ' + (rr ? rr.toFixed(2) + (rr < 2 ? ' ⚠️' : '') : 'n/a');

const L = ['🧭 *BẢNG 7 CÂU — ' + TICKER + '*', prov, ''];
L.push('① *Hiểu DN?* → DN này kiếm tiền bằng cách nào? Nói gọn 1 câu được không?');
L.push('   _Không nói được → chưa hiểu → bỏ qua._');
L.push('② Rẻ/đắt? ✅ ' + q2);
L.push('③ *Luận điểm?* → Mua vì TIN điều gì sắp xảy ra? Dấu hiệu nào cho thấy mình SAI?');
L.push('   _Viết được câu "nếu… thì tôi sai" mới nên mua._');
L.push('④ Bối cảnh? ✅ Khối ngoại: ' + q4);
L.push('⑤ *Thời điểm?* → Có xúc tác để tăng BÂY GIỜ (KQKD, cổ tức, hợp đồng…), hay chỉ "thấy rẻ ham" = bắt dao rơi?');
L.push('⑥ Kích thước & R:R? ✅ ' + q6);
L.push('⑦ Thoát? ✅ Cắt lỗ ' + fmtP(STOP) + (TARGET ? ' · Mục tiêu ' + fmtP(TARGET) : ''));
L.push('');
L.push('📝 ②④⑥⑦ bot lo. ①③⑤ là VIỆC CỦA ANH — gõ `/sâu ' + TICKER + '` để AI viết nháp ①③⑤ cho anh phản biện.');
L.push('_Mức giá là gợi ý kỹ thuật, không phải khuyến nghị mua/bán._');
return direct(L.join('\n'));

const meta = $('Bộ não bot').first().json;
const chatId = meta.chatId;
const prelude = meta.prelude || '';
const res = $input.first().json;
let text = '';
if (res && Array.isArray(res.content)) text = res.content.filter(b => b.type === 'text').map(b => b.text).join('\n').trim();
if (!text) { if (res && res.type === 'error' && res.error) text = '⚠️ Lỗi API: ' + (res.error.message || JSON.stringify(res.error)); else text = '⚠️ Không tạo được nháp (phản hồi rỗng).'; }
const full = prelude + '\n\n' + text + '\n\n_Nguồn: VNDirect + Vietstock(toàn văn) + Google News · nháp bởi Claude · KHÔNG phải khuyến nghị · ROE/BCTC tự kiểm chứng_';
const SIZE = 3800; const out = []; let s = full;
